"""KneeOps remote run EXP071_R34_LR_F3 (private). Generated by tools/remote_bundle.py kernel.

Finds the attached private datasets, runs run_remote.py on the Kaggle GPU and leaves results in
/kaggle/working/results/EXP071_R34_LR_F3. T4/P100 have no native bf16, so the trainer runs with --amp fp16.
"""
import glob, os, subprocess, sys, time
TAG = 'EXP071_R34_LR_F3'
TRAIN = '--fold 3 --arch resnet34.a1_in1k --res 224 --k 12 --k-eval 24 --bs 8 --accum 1 --epochs 20 --bb-lr 5e-4 --head-lr 1e-3 --oof-subsample 200 --select oof --workers 4 --amp fp16'
t0 = time.time()
print(subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"], capture_output=True, text=True).stdout)
hits = glob.glob("/kaggle/input/**/run_remote.py", recursive=True)
assert hits, "knee-raptor-tools dataset not attached"
tools = os.path.dirname(hits[0])
corpus = os.path.dirname(glob.glob("/kaggle/input/**/vols_shard00.npy", recursive=True)[0])
print("tools", tools, "| corpus", corpus, flush=True)
cmd = [sys.executable, os.path.join(tools, "run_remote.py"), "--tag", TAG, "--tools", tools, "--corpus", corpus, "--train", TRAIN, "--no-upload"]
code = subprocess.run(cmd).returncode
print(f"exit {code} after {time.time() - t0:.0f}s", flush=True)
sys.exit(code)
